    setIsLoading(true);
    const unsubSettings = onSnapshot(doc(db, 'settings', 'main'), (snap) => setSettings(snap.exists() ? (snap.data() as Settings) : null));
    const unsubProducts = onSnapshot(query(collection(db, 'products'), orderBy('createdAt', 'desc')), (snap) => {
        setProducts(snap.docs.map(d => ({ id: d.id, ...d.data() } as Product)));
        setIsLoading(false);
    });
    const unsubCoupons = onSnapshot(query(collection(db, 'coupons'), orderBy('createdAt', 'desc')), (snap) => setCoupons(snap.docs.map(d => ({ id: d.id, ...d.data() } as Coupon))));
    const unsubBanners = onSnapshot(query(collection(db, 'banners'), orderBy('createdAt', 'desc')), (snap) => setBanners(snap.docs.map(d => ({ id: d.id, ...d.data() } as Banner))));
    const unsubUpdates = onSnapshot(query(collection(db, 'updatePosts'), orderBy('createdAt', 'desc')), (snap) => setUpdatePosts(snap.docs.map(d => ({ id: d.id, ...d.data() } as UpdatePost))));

    let unsubOrders = () => {}, unsubChat = () => {};
    const unsubAuth = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      unsubOrders(); unsubChat();
      if (currentUser) {
        unsubOrders = onSnapshot(query(collection(db, 'orders'), orderBy('createdAt', 'desc')), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...d.data() } as Order))));
        unsubChat = onSnapshot(query(collection(db, "chatMessages"), orderBy("timestamp", "asc")), (snap) => setChatMessages(snap.docs.map(d => ({ id: d.id, ...d.data() } as ChatMessage))));
      } else { setOrders([]); setChatMessages([]); }
    });

    return () => {
      unsubSettings(); unsubProducts(); unsubCoupons(); unsubBanners();
      unsubUpdates(); unsubOrders(); unsubChat(); unsubAuth();
    };
  }, []);

  const value = {
    products, cart, orders, settings, chatMessages, coupons, banners, updatePosts,
    isLoading, error, user, wishlist, activeCustomer, customerOrders,
    addToCart, removeFromCart, updateCartQuantity, clearCart,
    addProduct, updateProduct, deleteProduct, toggleProductVisibility, moveProduct, copyProduct,
    addOrder, updateOrderStatus, deleteOrder,
    sendChatMessage, sendAdminReply, deleteChatMessage,
    updateSettings, addCategory, deleteCategory, updateCategory, moveCategory, copyCategory,
    addUpdatePost, updateUpdatePost, deleteUpdatePost,
    toggleWishlist, uploadFile, deleteFile, uploadApp, deleteApp,
    login, register, logout, trackWithEmailAndPhone, customerLogout,
    addCoupon, updateCoupon, deleteCoupon, addBanner, updateBanner, deleteBanner,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { useStore } from '../hooks/useStore';
import { Product } from '../types';
import { safeLower } from '../utils/helpers';
import { ProductCard } from '../components/ProductCard';
import { Spinner } from '../components/ui/Spinner';
import { Icons } from '../components/icons/Icons';
import { GoogleGenAI } from '@google/genai';

const Search = () => {
    const location = useLocation();
    const { products, isLoading: areProductsLoading } = useStore();

    const [searchResults, setSearchResults] = useState<Product[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isAiEnhanced, setIsAiEnhanced] = useState(false);
    const [apiError, setApiError] = useState<string | null>(null);

    const query = useMemo(() => new URLSearchParams(location.search).get('q') || '', [location.search]);

    useEffect(() => {
        const performAdvancedSearch = async () => {
            setIsLoading(true);
            setIsAiEnhanced(false);
            setApiError(null);

            const lowerQuery = safeLower(query);
            // Splitting query into words for token matching
            let allSearchTokens = lowerQuery.split(/\s+/).filter(t => t.length > 2);
            // Always keep the original query as a single token for exact matching
            if (lowerQuery.trim()) {
                allSearchTokens.unshift(lowerQuery.trim());
            }

            // Gemini API Integration - Hardcoded Key as requested
            const apiKey = "AIzaSyDkY6cyCXJtZAPNmWmqm7iloIJXf2-4Q1M";

            try {
                const ai = new GoogleGenAI({ apiKey });
                const prompt = `A user searched for "${query}" on an e-commerce site specializing in clothing and accessories. Provide a short, comma-separated list of related product keywords to enhance the search results. For example, if the search is "shirt", you could return "t-shirt, pants, jeans, formal shirt, casual wear, apparel". Return only the keywords.`;

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt,
                });

                const relatedTermsText = response.text;
                if (relatedTermsText) {
                    const relatedTerms = relatedTermsText.split(',').map(term => safeLower(term.trim()).replace(/\"/g, ''));
                    allSearchTokens = [...new Set([...allSearchTokens, ...relatedTerms])];
                    setIsAiEnhanced(true);
                }
            } catch (error: any) {
                console.error("Gemini API call failed, falling back to basic search:", error);
                const errorMessage = error.toString().toLowerCase();
                if (errorMessage.includes('permission_denied') || errorMessage.includes('api key not valid')) {
                    setApiError("AI-enhanced search is unavailable due to an invalid API key.");
                } else {
                    setApiError("Could not connect to the AI service. Using standard search.");
                }
            }

            const scoredResults = products.map(product => {
                if (!product.isVisible) return { product, score: 0 };

                let score = 0;
                const name = safeLower(product.name);
                const category = safeLower(product.category);
                const description = safeLower(product.description);

                // HIGHEST PRIORITY: Poora search sentence agar name mein kahi bhi ho
                if (name.includes(lowerQuery)) {
                    score += 200;
                }

                // Tokens match check
                allSearchTokens.forEach(token => {
                    if (!token || token.length < 2) return;

                    if (name.includes(token)) {
                        // Bonus for exact query tokens
                        score += (lowerQuery.includes(token)) ? 20 : 5;
                    }
                    if (category.includes(token)) {
                        score += (lowerQuery.includes(token)) ? 10 : 2;
                    }
                    if (description.includes(token)) {
                        score += 1;
                    }
                });

                return { product, score };
            });

            const sortedProducts = scoredResults
                .filter(item => item.score > 0)
                .sort((a, b) => b.score - a.score)
                .map(item => item.product);

            setSearchResults(sortedProducts);
            setIsLoading(false);
        };

        if (!query) {
            setSearchResults([]);
            setIsLoading(false);
            return;
        }

        if (areProductsLoading) {
            setIsLoading(true);
            return;
        }

        performAdvancedSearch();

    }, [query, products, areProductsLoading]);

    return (
        <div className="space-y-6">
            <div className="text-center">
                <h1 className="text-3xl font-bold text-gray-800 flex items-center justify-center gap-2">
                    {isAiEnhanced && !apiError && <span title="AI-enhanced search results" className="text-transparent bg-clip-text bg-gradient-to-r from-teal-500 to-pink-500">✨</span>}
                    Search Results
                </h1>
                {query && <p className="text-gray-600 mt-1">Showing results for: <span className="font-semibold">"{query}"</span></p>}
            </div>

            {apiError && (
                 <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4" role="alert">
                    <div className="flex">
                        <div className="py-1"><svg className="fill-current h-6 w-6 text-yellow-500 mr-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M2.93 17.07A10 10 0 1 1 17.07 2.93 10 10 0 0 1 2.93 17.07zM9 5v6h2V5H9zm0 8v2h2v-2H9z"/></svg></div>
                        <div>
                            <p className="font-bold">Note</p>
                            <p className="text-sm">{apiError} The search will continue with basic functionality.</p>
                        </div>
                    </div>
                </div>
            )}

            {isLoading ? (
                <div className="text-center py-16 text-gray-500">
                    <Spinner size="lg" />
                    <p className="mt-4 font-semibold">Searching for "{query}"...</p>
                    <p className="text-sm">Matching titles and enhancing with AI...</p>
                </div>
            ) : searchResults.length > 0 ? (
                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                    {searchResults.map(product => (
                        <ProductCard key={product.id} product={product} />
                    ))}
                </div>
            ) : (
                <div className="text-center py-16 text-gray-500">
                    <Icons.search className="w-16 h-16 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold">No products found</h3>
                    <p>We couldn't find anything matching your exact query. <br/>Try using shorter keywords or check the spelling.</p>
                </div>
            )}
        </div>
    );
};

export default Search;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Icons } from './icons/Icons';
import { Button } from './ui/Button';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// FIX: Explicitly extending from Component with Props and State generics to ensure props.children and state properties are correctly recognized by TypeScript.
export class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    error: null,
  };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error in React component:", error, errorInfo);
  }

  handleReload = () => {
    // Clear cache-busting reload flag if present from lazyRetry
    Object.keys(window.sessionStorage).forEach(key => {
        if(key.startsWith('retry-')) window.sessionStorage.removeItem(key);
    });
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-gray-50 p-4 text-center">
          <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-gray-100">
            <div className="bg-red-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
               <Icons.refresh className="w-8 h-8 text-red-500" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800 mb-2">Something went wrong</h1>
            <p className="text-gray-500 mb-6">
              We encountered an unexpected error while displaying this page.
            </p>

            {/* Safe error message display */}
            <div className="bg-gray-100 p-3 rounded text-left text-xs font-mono text-red-600 mb-6 overflow-auto max-h-32 border border-gray-200">
                {this.state.error?.message || 'Unknown Application Error'}
            </div>

            <Button onClick={this.handleReload} className="w-full" size="lg">
              Reload Application
            </Button>
            <p className="mt-4 text-xs text-gray-400">
              If the problem persists, please try clearing your browser cache.
            </p>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

