export const AppContext = createContext<AppContextType | undefined>(undefined);

const apiRequest = async (endpoint: string, body: any) => {
    try {
        const response = await fetch(endpoint, {
            method: 'POST',
            body: body,
        });
        if (!response.ok) throw new Error(`Server status: ${response.status}`);
        const result = await response.json();
        if (!result.success) throw new Error(result.error || 'API request failed');
        return result;
    } catch (error) {
        console.error(`API Error:`, error);
        throw error;
    }
};

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useLocalStorage<CartItem[]>('cart', []);
  const [wishlist, setWishlist] = useLocalStorage<string[]>('wishlist', []);
  const [orders, setOrders] = useState<Order[]>([]);
  const [settings, setSettings] = useState<Settings | null>(null);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [updatePosts, setUpdatePosts] = useState<UpdatePost[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [activeCustomer, setActiveCustomer] = useSessionStorage<{ email: string, phone: string } | null>('active-tracking-id', null);
  const [customerOrders, setCustomerOrders] = useState<Order[]>([]);

  const uploadFile = useCallback(async (file: File): Promise<string> => {
    const formData = new FormData();
    formData.append('file', file);
    const result = await apiRequest('/api/upload.php', formData);
    return result.url;
  }, []);

  const deleteFile = useCallback(async (fileUrl: string): Promise<void> => {
    if (!fileUrl?.includes('/uploads/')) return;
    await apiRequest('/api/delete.php', JSON.stringify({ fileUrl }));
  }, []);

  const addToCart = (product: Product, quantity: number, selectedSizes?: Record<string, string>, additionalInfo?: string) => {
    setCart(prev => {
      const itemKey = generateCartItemKey({ id: product.id, selectedSizes });
      const existing = prev.find(i => generateCartItemKey(i) === itemKey);
      if (existing) return prev.map(i => generateCartItemKey(i) === itemKey ? { ...i, quantity: i.quantity + quantity } : i);
      return [...prev, { id: product.id, customId: product.customId, name: product.name, price: product.price, image: product.images[0], quantity, selectedSizes, deliveryTime: product.deliveryTime, easyReturn: product.easyReturn, returnPolicy: product.returnPolicy, additionalInfo, shippingFee: product.shippingFee }];
    });
    alert(`${product.name} added to cart!`);
  };

  const removeFromCart = (productId: string, selectedSizes?: Record<string, string>) => {
    const itemKey = generateCartItemKey({ id: productId, selectedSizes });
    setCart(prev => prev.filter(i => generateCartItemKey(i) !== itemKey));
  };

  const updateCartQuantity = (productId: string, quantity: number, selectedSizes?: Record<string, string>) => {
      if (quantity <= 0) removeFromCart(productId, selectedSizes);
      else {
          const itemKey = generateCartItemKey({ id: productId, selectedSizes });
          setCart(prev => prev.map(i => generateCartItemKey(i) === itemKey ? { ...i, quantity } : i));
      }
  };

  const clearCart = () => setCart([]);

  const addProduct = async (data: Omit<Product, 'id' | 'createdAt'>) => await addDoc(collection(db, 'products'), { ...data, createdAt: Date.now() });
  const updateProduct = async (data: Product) => await setDoc(doc(db, 'products', data.id), data);
  const deleteProduct = async (id: string) => {
    const prod = products.find(p => p.id === id);
    if (prod?.images) await Promise.all(prod.images.map(url => deleteFile(url)));
    await deleteDoc(doc(db, 'products', id));
  };
  const toggleProductVisibility = async (id: string, isVisible: boolean) => await updateDoc(doc(db, 'products', id), { isVisible });
  const moveProduct = async (id: string, newCategory: string) => await updateDoc(doc(db, 'products', id), { category: newCategory });
  const copyProduct = async (id: string, cat: string) => {
    const prod = products.find(p => p.id === id);
    if (!prod) throw new Error("Product not found");
    const { id: _, createdAt: __, ...newData } = prod;
    await addProduct({ ...newData, category: cat, name: `${newData.name} (Copy)` });
  };

  const addOrder = async (orderData: Omit<Order, 'id' | 'createdAt' | 'customerId'>) => {
    const phone = normalizePhone(orderData.customerPhone);
    await addDoc(collection(db, 'orders'), { 
        ...orderData, 
        customerPhone: phone, 
        email: orderData.email.trim().toLowerCase(),
        createdAt: Date.now() 
    });
    clearCart();
  };

  const updateOrderStatus = async (id: string, status: OrderStatus) => await updateDoc(doc(db, 'orders', id), { status });
  const deleteOrder = async (id: string) => await deleteDoc(doc(db, 'orders', id));

  const updateSettings = async (data: Settings) => await setDoc(doc(db, 'settings', 'main'), data, { merge: true });

  const addCategory = async (name: string, parentId: string | null, imageUrl?: string, bannerImageUrls?: string[]) => {
    if (!settings) return;
    const trimmedName = name.trim();
    const existingCategories = (settings.categories || []).filter(c => c && typeof c.name === 'string');
    if (!trimmedName) { alert("Category name cannot be empty."); return; }
    if (existingCategories.some(c => c.name.toLowerCase() === trimmedName.toLowerCase())) { alert(`Category "${trimmedName}" already exists.`); return; }
    const newCategory: Category = { id: `cat_${Date.now()}`, name: trimmedName, parentId, isVisible: true, ...(imageUrl && { imageUrl }), ...(bannerImageUrls && bannerImageUrls.length > 0 && { bannerImageUrls }) };
    await updateSettings({ ...settings, categories: [...existingCategories, newCategory] });
  };

  const deleteCategory = async (id: string) => {
    if (!settings?.categories) return;
    const allCategories = settings.categories;
    const remainingCategories = allCategories.filter(c => c.id !== id && c.parentId !== id);
    await updateSettings({ ...settings, categories: remainingCategories });
  };

  const updateCategory = async (id: string, newData: Partial<Omit<Category, 'id'>>) => {
    if (!settings?.categories) return;
    const updatedCategories = settings.categories.map(c => c.id === id ? { ...c, ...newData } : c);
    await updateSettings({ ...settings, categories: updatedCategories });
  };

  const moveCategory = async (categoryId: string, newParentId: string | null) => await updateCategory(categoryId, { parentId: newParentId });
  const copyCategory = async (categoryId: string, newParentId: string | null) => {
    if (!settings?.categories) return;
    const cat = settings.categories.find(c => c.id === categoryId);
    if (cat) await addCategory(`${cat.name} Copy`, newParentId, cat.imageUrl, cat.bannerImageUrls);
  };

  const uploadApp = useCallback(async (file: File) => {
    const url = await uploadFile(file);
    await updateSettings({ ...settings!, appDownloadUrl: url, appFileName: file.name });
  }, [settings, uploadFile]);

  const deleteApp = useCallback(async () => {
    if (settings?.appDownloadUrl) {
      await deleteFile(settings.appDownloadUrl);
      await updateSettings({ ...settings!, appDownloadUrl: '', appFileName: '' });
    }
  }, [settings, deleteFile]);

  const addUpdatePost = async (post: Omit<UpdatePost, 'id' | 'createdAt'>) => await addDoc(collection(db, 'updatePosts'), { ...post, createdAt: Date.now() });
  const updateUpdatePost = async (post: UpdatePost) => await setDoc(doc(db, 'updatePosts', post.id), post);
  const deleteUpdatePost = async (post: UpdatePost) => await deleteDoc(doc(db, 'updatePosts', post.id));

  const sendChatMessage = async (text: string, sessionId: string) => await addDoc(collection(db, 'chatMessages'), { sessionId, text, sender: 'user', timestamp: Date.now() });
  const sendAdminReply = async (sessionId: string, text: string) => await addDoc(collection(db, 'chatMessages'), { sessionId, text, sender: 'admin', timestamp: Date.now() });
  const deleteChatMessage = async (id: string) => await deleteDoc(doc(db, 'chatMessages', id));

  const toggleWishlist = (id: string) => setWishlist(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);

  const login = async (email: string, pass: string) => await signInWithEmailAndPassword(auth, email, pass);
  const register = async (email: string, pass: string) => await createUserWithEmailAndPassword(auth, email, pass);
  const logout = async () => await signOut(auth);

  const trackWithEmailAndPhone = async (email: string, phone: string) => {
      const normPhone = normalizePhone(phone);
      const inputEmail = email.trim().toLowerCase();

      // Query by phone from orders collection to find matching orders
      const q = query(collection(db, 'orders'), where('customerPhone', '==', normPhone));
      const snap = await getDocs(q);

      if (!snap.empty) {
          // Filter by email in memory
          const foundOrders = snap.docs
            .map(d => ({ id: d.id, ...d.data() } as Order))
            .filter(o => o.email?.toLowerCase() === inputEmail);

          if (foundOrders.length > 0) {
              setActiveCustomer({ email: inputEmail, phone: normPhone });
              return true;
          }
      }
      return false;
  };

  const customerLogout = () => {
      setActiveCustomer(null);
      setCustomerOrders([]);
  };

  useEffect(() => {
    if (!activeCustomer) return;
    // Realtime listener for tracked orders
    const q = query(collection(db, 'orders'), where('customerPhone', '==', activeCustomer.phone));
    const unsub = onSnapshot(q, snap => {
        const results = snap.docs
            .map(d => ({ id: d.id, ...d.data() } as Order))
            .filter(o => o.email?.toLowerCase() === activeCustomer.email);

        // Sort by createdAt DESC in memory
        setCustomerOrders(results.sort((a, b) => b.createdAt - a.createdAt));
    });
    return () => unsub();
  }, [activeCustomer]);

  const addCoupon = async (data: Omit<Coupon, 'id' | 'createdAt'>) => await addDoc(collection(db, 'coupons'), { ...data, createdAt: Date.now() });
  const updateCoupon = async (data: Coupon) => await setDoc(doc(db, 'coupons', data.id), data);
  const deleteCoupon = async (id: string) => await deleteDoc(doc(db, 'coupons', id));

  const addBanner = async (data: Omit<Banner, 'id' | 'createdAt'>) => await addDoc(collection(db, 'banners'), { ...data, createdAt: Date.now() });
  const updateBanner = async (data: Banner) => await setDoc(doc(db, 'banners', data.id), data);
  const deleteBanner = async (banner: Banner) => {
    if(banner.imageUrl) await deleteFile(banner.imageUrl);
    await deleteDoc(doc(db, 'banners', banner.id));
  };

  useEffect(() => {
    setIsLoading(true);
    const unsubSettings = onSnapshot(doc(db, 'settings', 'main'), (snap) => setSettings(snap.exists() ? (snap.data() as Settings) : null));
    const unsubProducts = onSnapshot(query(collection(db, 'products'), orderBy('createdAt', 'desc')), (snap) => {
        setProducts(snap.docs.map(d => ({ id: d.id, ...d.data() } as Product)));
        setIsLoading(false);
    });
    const unsubCoupons = onSnapshot(query(collection(db, 'coupons'), orderBy('createdAt', 'desc')), (snap) => setCoupons(snap.docs.map(d => ({ id: d.id, ...d.data() } as Coupon))));
    const unsubBanners = onSnapshot(query(collection(db, 'banners'), orderBy('createdAt', 'desc')), (snap) => setBanners(snap.docs.map(d => ({ id: d.id, ...d.data() } as Banner))));
    const unsubUpdates = onSnapshot(query(collection(db, 'updatePosts'), orderBy('createdAt', 'desc')), (snap) => setUpdatePosts(snap.docs.map(d => ({ id: d.id, ...d.data() } as UpdatePost))));

    let unsubOrders = () => {}, unsubChat = () => {};
    const unsubAuth = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      unsubOrders(); unsubChat();
      if (currentUser) {
        unsubOrders = onSnapshot(query(collection(db, 'orders'), orderBy('createdAt', 'desc')), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...d.data() } as Order))));
        unsubChat = onSnapshot(query(collection(db, "chatMessages"), orderBy("timestamp", "asc")), (snap) => setChatMessages(snap.docs.map(d => ({ id: d.id, ...d.data() } as ChatMessage))));
      } else { setOrders([]); setChatMessages([]); }
    });

    return () => {
      unsubSettings(); unsubProducts(); unsubCoupons(); unsubBanners();
      unsubUpdates(); unsubOrders(); unsubChat(); unsubAuth();
    };
  }, []);

  const value = {
    products, cart, orders, settings, chatMessages, coupons, banners, updatePosts,
    isLoading, error, user, wishlist, activeCustomer, customerOrders,
    addToCart, removeFromCart, updateCartQuantity, clearCart,
    addProduct, updateProduct, deleteProduct, toggleProductVisibility, moveProduct, copyProduct,
    addOrder, updateOrderStatus, deleteOrder,
    sendChatMessage, sendAdminReply, deleteChatMessage,
    updateSettings, addCategory, deleteCategory, updateCategory, moveCategory, copyCategory,
    addUpdatePost, updateUpdatePost, deleteUpdatePost,
    toggleWishlist, uploadFile, deleteFile, uploadApp, deleteApp,
    login, register, logout, trackWithEmailAndPhone, customerLogout,
    addCoupon, updateCoupon, deleteCoupon, addBanner, updateBanner, deleteBanner,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { useStore } from '../hooks/useStore';
import { Product } from '../types';
import { safeLower } from '../utils/helpers';
import { ProductCard } from '../components/ProductCard';
import { Spinner } from '../components/ui/Spinner';
import { Icons } from '../components/icons/Icons';
import { GoogleGenAI } from '@google/genai';

const Search = () => {
    const location = useLocation();
    const { products, isLoading: areProductsLoading } = useStore();

    const [searchResults, setSearchResults] = useState<Product[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isAiEnhanced, setIsAiEnhanced] = useState(false);
    const [apiError, setApiError] = useState<string | null>(null);

    const query = useMemo(() => new URLSearchParams(location.search).get('q') || '', [location.search]);

    useEffect(() => {
        const performAdvancedSearch = async () => {
            setIsLoading(true);
            setIsAiEnhanced(false);
            setApiError(null);

            const lowerQuery = safeLower(query);
            // Splitting query into words for token matching
            let allSearchTokens = lowerQuery.split(/\s+/).filter(t => t.length > 2);
            // Always keep the original query as a single token for exact matching
            if (lowerQuery.trim()) {
                allSearchTokens.unshift(lowerQuery.trim());
            }

            try {
                // Gemini API Integration - Hardcoded Key as requested by the user
                const apiKey = "AIzaSyDkY6cyCXJtZAPNmWmqm7iloIJXf2-4Q1M";
                const ai = new GoogleGenAI({ apiKey });
                const prompt = `A user searched for "${query}" on an e-commerce site specializing in clothing and accessories. Provide a short, comma-separated list of related product keywords to enhance the search results. For example, if the search is "shirt", you could return "t-shirt, pants, jeans, formal shirt, casual wear, apparel". Return only the keywords.`;

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt,
                });

                const relatedTermsText = response.text;
                if (relatedTermsText) {
                    const relatedTerms = relatedTermsText.split(',').map(term => safeLower(term.trim()).replace(/\"/g, ''));
                    allSearchTokens = [...new Set([...allSearchTokens, ...relatedTerms])];
                    setIsAiEnhanced(true);
                }
            } catch (error: any) {
                console.error("Gemini API call failed, falling back to basic search:", error);
                const errorMessage = error.toString().toLowerCase();
                if (errorMessage.includes('permission_denied') || errorMessage.includes('api key not valid')) {
                    setApiError("AI-enhanced search is unavailable due to an invalid API key.");
                } else {
                    setApiError("Could not connect to the AI service. Using standard search.");
                }
            }

            const scoredResults = products.map(product => {
                if (!product.isVisible) return { product, score: 0 };

                let score = 0;
                const name = safeLower(product.name);
                const category = safeLower(product.category);
                const description = safeLower(product.description);

                // HIGHEST PRIORITY: Poora search sentence agar name mein kahi bhi ho
                if (name.includes(lowerQuery)) {
                    score += 200;
                }

                // Tokens match check
                allSearchTokens.forEach(token => {
                    if (!token || token.length < 2) return;

                    if (name.includes(token)) {
                        // Bonus for exact query tokens
                        score += (lowerQuery.includes(token)) ? 20 : 5;
                    }
                    if (category.includes(token)) {
                        score += (lowerQuery.includes(token)) ? 10 : 2;
                    }
                    if (description.includes(token)) {
                        score += 1;
                    }
                });

                return { product, score };
            });

            const sortedProducts = scoredResults
                .filter(item => item.score > 0)
                .sort((a, b) => b.score - a.score)
                .map(item => item.product);

            setSearchResults(sortedProducts);
            setIsLoading(false);
        };

        if (!query) {
            setSearchResults([]);
            setIsLoading(false);
            return;
        }

        if (areProductsLoading) {
            setIsLoading(true);
            return;
        }

        performAdvancedSearch();

    }, [query, products, areProductsLoading]);

    return (
        <div className="space-y-6">
            <div className="text-center">
                <h1 className="text-3xl font-bold text-gray-800 flex items-center justify-center gap-2">
                    {isAiEnhanced && !apiError && <span title="AI-enhanced search results" className="text-transparent bg-clip-text bg-gradient-to-r from-teal-500 to-pink-500">✨</span>}
                    Search Results
                </h1>
                {query && <p className="text-gray-600 mt-1">Showing results for: <span className="font-semibold">"{query}"</span></p>}
            </div>

            {apiError && (
                 <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4" role="alert">
                    <div className="flex">
                        <div className="py-1"><svg className="fill-current h-6 w-6 text-yellow-500 mr-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M2.93 17.07A10 10 0 1 1 17.07 2.93 10 10 0 0 1 2.93 17.07zM9 5v6h2V5H9zm0 8v2h2v-2H9z"/></svg></div>
                        <div>
                            <p className="font-bold">Note</p>
                            <p className="text-sm">{apiError} The search will continue with basic functionality.</p>
                        </div>
                    </div>
                </div>
            )}

            {isLoading ? (
                <div className="text-center py-16 text-gray-500">
                    <Spinner size="lg" />
                    <p className="mt-4 font-semibold">Searching for "{query}"...</p>
                    <p className="text-sm">Matching titles and enhancing with AI...</p>
                </div>
            ) : searchResults.length > 0 ? (
                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
                    {searchResults.map(product => (
                        <ProductCard key={product.id} product={product} />
                    ))}
                </div>
            ) : (
                <div className="text-center py-16 text-gray-500">
                    <Icons.search className="w-16 h-16 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold">No products found</h3>
                    <p>We couldn't find anything matching your exact query. <br/>Try using shorter keywords or check the spelling.</p>
                </div>
            )}
        </div>
    );
};

