import React, { useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { useStore } from '../../hooks/useStore';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Spinner } from '../../components/ui/Spinner';
import { Icons } from '../../components/icons/Icons';
import { Category } from '../../types';
import { safeLower } from '../../utils/helpers';
import { EditCategoryModal } from '../../components/admin/EditCategoryModal';
import { ImageWithFallback } from '../../components/ui/ImageWithFallback';
import { MoveCopyCategoryModal } from '../../components/admin/MoveCopyCategoryModal';

const ManageCategories = () => {
    const { settings, addCategory, deleteCategory, updateCategory, isLoading, products, uploadFile } = useStore();
    const [newCategoryName, setNewCategoryName] = useState('');
    const [imageInputMode, setImageInputMode] = useState<'upload' | 'url'>('upload');
    const [newCategoryImageFile, setNewCategoryImageFile] = useState<File | null>(null);
    const [newCategoryImageUrl, setNewCategoryImageUrl] = useState('');

    // State for multiple banners
    const [bannerInputMode, setBannerInputMode] = useState<'upload' | 'url'>('upload');
    const [newCategoryBannerUrls, setNewCategoryBannerUrls] = useState<string[]>([]);
    const [newBannerUrlInput, setNewBannerUrlInput] = useState('');

    const [isSubmitting, setIsSubmitting] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [editingCategory, setEditingCategory] = useState<Category | null>(null);
    const [isMoveCopyModalOpen, setIsMoveCopyModalOpen] = useState(false);
    const [categoryToMoveCopy, setCategoryToMoveCopy] = useState<Category | null>(null);

    const categories = useMemo(() => (settings?.categories || []).filter(c => c && c.id), [settings]);

    const productCounts = useMemo(() => {
        const counts: Record<string, number> = {};
        products.forEach(p => {
            counts[p.category] = (counts[p.category] || 0) + 1;
        });
        return counts;
    }, [products]);

    const handleAddBannerUrl = () => {
        if (newBannerUrlInput.trim()) {
            setNewCategoryBannerUrls(prev => [...prev, newBannerUrlInput.trim()]);
            setNewBannerUrlInput('');
        }
    };

    const handleBannerUpload = async (file: File) => {
        try {
            const url = await uploadFile(file);
            setNewCategoryBannerUrls(prev => [...prev, url]);
        } catch (error) { console.error("Banner upload failed", error); }
    };

    const handleAddCategory = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCategoryName.trim()) return;
        setIsSubmitting(true);
        try {
            let imageUrl: string | undefined = undefined;
            if (imageInputMode === 'upload' && newCategoryImageFile) imageUrl = await uploadFile(newCategoryImageFile);
            else if (imageInputMode === 'url' && newCategoryImageUrl.trim()) imageUrl = newCategoryImageUrl.trim();

            await addCategory(newCategoryName, null, imageUrl, newCategoryBannerUrls);
            setNewCategoryName(''); setNewCategoryImageFile(null); setNewCategoryImageUrl('');
            setNewCategoryBannerUrls([]); setNewBannerUrlInput('');
        } catch (error) {
            console.error("Failed to add category", error);
        } finally { setIsSubmitting(false); }
    };

    const openEditModal = (category: Category) => {
        setEditingCategory(category);
        setIsEditModalOpen(true);
    };

    const openMoveCopyModal = (category: Category) => {
        setCategoryToMoveCopy(category);
        setIsMoveCopyModalOpen(true);
    };

    const topLevelCategories = useMemo(() => {
        const lowerSearch = safeLower(searchTerm);
        return categories.filter(c => !c.parentId && safeLower(c.name).includes(lowerSearch));
    }, [categories, searchTerm]);

    return (
        <div>
            <h1 className="text-3xl font-bold text-gray-800 mb-4">Manage Categories</h1>
            <div className="bg-white p-4 rounded-lg shadow-sm mb-6 border-t-4 border-teal-500">
                <h2 className="text-xl font-bold mb-3">Add New Parent Category</h2>
                <form onSubmit={handleAddCategory} className="space-y-3">
                    <Input label="Category Name" placeholder="e.g., Men's Fashion" value={newCategoryName} onChange={e => setNewCategoryName(e.target.value)} required />
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">Category Image (Optional)</label>
                        <div className="flex gap-2 border-b pb-3 mb-3"><Button type="button" size="sm" variant={imageInputMode === 'upload' ? 'primary' : 'secondary'} onClick={() => setImageInputMode('upload')}>Upload</Button><Button type="button" size="sm" variant={imageInputMode === 'url' ? 'primary' : 'secondary'} onClick={() => setImageInputMode('url')}>URL</Button></div>
                        {imageInputMode === 'upload' ? <Input type="file" accept="image/*" onChange={e => setNewCategoryImageFile(e.target.files ? e.target.files[0] : null)} /> : <Input type="url" placeholder="https://example.com/image.png" value={newCategoryImageUrl} onChange={e => setNewCategoryImageUrl(e.target.value)} />}
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">Banner Images (Optional)</label>
                        <div className="flex gap-2 border-b pb-3 mb-3"><Button type="button" size="sm" variant={bannerInputMode === 'upload' ? 'primary' : 'secondary'} onClick={() => setBannerInputMode('upload')}>Upload</Button><Button type="button" size="sm" variant={bannerInputMode === 'url' ? 'primary' : 'secondary'} onClick={() => setBannerInputMode('url')}>URL</Button></div>
                        {bannerInputMode === 'upload' ? <Input type="file" accept="image/*" multiple onChange={e => { if (e.target.files) Array.from(e.target.files).forEach(handleBannerUpload) }} /> : <div className="flex gap-2"><Input type="url" placeholder="https://example.com/banner.png" value={newBannerUrlInput} onChange={e => setNewBannerUrlInput(e.target.value)} /><Button type="button" onClick={handleAddBannerUrl}>Add</Button></div>}
                        <div className="mt-2 grid grid-cols-3 gap-2">
                          {newCategoryBannerUrls.map((url, i) => <div key={i} className="relative"><ImageWithFallback src={url} className="w-full h-16 object-cover rounded" /><Button type="button" variant="danger" size="xs" className="absolute top-1 right-1" onClick={() => setNewCategoryBannerUrls(p => p.filter((_, idx) => idx !== i))}><Icons.trash className="w-3 h-3"/></Button></div>)}
                        </div>
                    </div>
                    <Button type="submit" disabled={isSubmitting}>{isSubmitting ? <Spinner size="sm" /> : 'Create Category'}</Button>
                </form>
            </div>
            <div className="bg-white p-4 rounded-lg shadow-sm">
                <h2 className="text-xl font-bold mb-3">Existing Parent Categories</h2>
                <div className="mb-4"><Input placeholder="Search categories..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} /></div>
                {isLoading && categories.length === 0 ? <div className="text-center py-8"><Spinner /></div> : topLevelCategories.length > 0 ? (
                    <div className="space-y-2">
                        {topLevelCategories.map(category => (
                            <div key={category.id} className="flex flex-col sm:flex-row justify-between items-center bg-gray-50 p-3 rounded-md gap-3">
                                <div className="flex items-center gap-4 flex-grow">
                                    <ImageWithFallback src={category.imageUrl} alt={category.name} className="w-12 h-12 rounded-md object-cover"/>
                                    <div>
                                        <span className="font-medium text-gray-800">{category.name}</span>
                                        <span className="ml-3 text-sm text-gray-500 block">({productCounts[category.name] || 0} products)</span>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 flex-shrink-0">
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs text-gray-500">Visible</span>
                                        <button onClick={() => updateCategory(category.id, { isVisible: !category.isVisible })} className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${category.isVisible ? 'bg-teal-600' : 'bg-gray-200'}`}>
                                            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${category.isVisible ? 'translate-x-6' : 'translate-x-1'}`} />
                                        </button>
                                    </div>
                                    <Link to={`/admin/categories/${encodeURIComponent(category.id)}`}><Button variant="outline" size="sm">Manage</Button></Link>
                                    <Button variant="secondary" size="sm" onClick={() => openMoveCopyModal(category)}><Icons.copy className="w-4 h-4" /></Button>
                                    <Button variant="secondary" size="sm" onClick={() => openEditModal(category)}><Icons.edit className="w-4 h-4"/></Button>
                                    <Button variant="danger" size="sm" onClick={() => deleteCategory(category.id)}><Icons.trash className="w-4 h-4" /></Button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : <p className="text-center py-8 text-gray-500">No top-level categories found.</p>}
            </div>
            <EditCategoryModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} category={editingCategory} onSave={updateCategory} />
            <MoveCopyCategoryModal isOpen={isMoveCopyModalOpen} onClose={() => setIsMoveCopyModalOpen(false)} category={categoryToMoveCopy} />
        </div>
    );
};

export default ManageCategories;

import React, { useState, useEffect, useMemo } from 'react';
import { useStore } from '../../hooks/useStore';
import { Product, SizeCategory, Category } from '../../types';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Textarea } from '../ui/Textarea';
import { Spinner } from '../ui/Spinner';
import { Icons } from '../icons/Icons';
import { ImageWithFallback } from '../ui/ImageWithFallback';

interface ProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  product: Product | null;
  categoryLock?: string;
}

// Helper to build a flat list of categories with indentation for the dropdown
const getCategoryOptions = (categories: Category[]): { id: string, name: string }[] => {
    type CategoryNode = Category & { children: CategoryNode[] };
    const categoryMap = new Map<string, CategoryNode>();
    const roots: CategoryNode[] = [];
    const options: { id: string, name: string }[] = [];

    categories.forEach(c => categoryMap.set(c.id, { ...c, children: [] }));
    categories.forEach(c => {
        if (c.parentId && categoryMap.has(c.parentId)) categoryMap.get(c.parentId)?.children.push(categoryMap.get(c.id)!);
        else roots.push(categoryMap.get(c.id)!);
    });

    const traverse = (node: CategoryNode, depth: number) => {
        options.push({ id: node.name, name: `${'— '.repeat(depth)}${node.name}` });
        node.children.forEach(child => traverse(child, depth + 1));
    };
    roots.forEach(root => traverse(root, 0));
    return options;
};

export const ProductModal: React.FC<ProductModalProps> = ({ isOpen, onClose, product, categoryLock }) => {
  const { addProduct, updateProduct, uploadFile, settings } = useStore();
  const [formData, setFormData] = useState<Omit<Product, 'id' | 'createdAt'>>({ name: '', customId: '', description: '', price: 0, oldPrice: 0, category: '', images: [], isVisible: true, sizeCategories: [], deliveryTime: 'Delivery in 3 Days', easyReturn: false, returnPolicy: '', shippingFee: 0, freeDelivery: false });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const [newSizeInputs, setNewSizeInputs] = useState<Record<number, string>>({});
  const [imageInputMode, setImageInputMode] = useState<'upload' | 'url'>('upload');
  const [imageUrl, setImageUrl] = useState('');
  const [newCategoryName, setNewCategoryName] = useState('');

  const categoryOptions = useMemo(() => {
    const allCats = settings?.categories || [];
    // Only allow selecting child categories (categories that have a parent)
    const childCategoryNames = new Set(allCats.filter(c => c.parentId).map(c => c.name));
    return getCategoryOptions(allCats).filter(opt => childCategoryNames.has(opt.id));
  }, [settings?.categories]);

  useEffect(() => {
    if (product) {
      setFormData({
        name: product.name, customId: product.customId || '', description: product.description, price: product.price, oldPrice: product.oldPrice || 0,
        category: product.category, images: product.images, isVisible: product.isVisible, sizeCategories: product.sizeCategories || [],
        deliveryTime: product.deliveryTime || 'Delivery in 3 Days', easyReturn: product.easyReturn || false,
        returnPolicy: product.returnPolicy || '', shippingFee: product.shippingFee || 0, freeDelivery: product.freeDelivery || false
      });
    } else {
      setFormData({ 
          name: '', customId: '', description: '', price: 0, oldPrice: 0, 
          category: categoryLock || categoryOptions[0]?.id || '', 
          images: [], isVisible: true, sizeCategories: [], deliveryTime: 'Delivery in 3 Days', 
          easyReturn: false, returnPolicy: '', shippingFee: 0, freeDelivery: false 
      });
    }
    setUploadError(''); setIsUploading(false); setNewCategoryName(''); setNewSizeInputs({});
  }, [product, isOpen, settings, categoryLock, categoryOptions]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    if (type === 'checkbox') setFormData({ ...formData, [name]: (e.target as HTMLInputElement).checked });
    else setFormData({ ...formData, [name]: type === 'number' ? parseFloat(value) : value });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files) return;
      setIsUploading(true); setUploadError('');
      try {
        const uploadedUrls: string[] = [];
        // FIX: Replaced for...of with a classic for-loop to iterate over the FileList.
        // This avoids potential type inference issues in some TypeScript configurations,
        // ensuring each `file` is correctly typed as a File object before being passed to `uploadFile`.
        for (let i = 0; i < e.target.files.length; i++) {
          const file = e.target.files[i];
          const url = await uploadFile(file);
          uploadedUrls.push(url);
        }
        setFormData(prev => ({ ...prev, images: [...prev.images, ...uploadedUrls]}));
      } catch (err: any) { setUploadError(err.message || 'Upload error.'); } 
      finally { setIsUploading(false); }
  };

  const handleAddImageUrl = () => {
    if (imageUrl.trim()) {
        try { new URL(imageUrl.trim()); setFormData(prev => ({ ...prev, images: [...prev.images, imageUrl.trim()] })); setImageUrl(''); } 
        catch (_) { alert('Invalid URL.'); }
    }
  };

  const handleCreateAndAddCategory = () => {
    const trimmedName = newCategoryName.trim();
    if (!trimmedName || formData.sizeCategories?.some(c => c.categoryName.toLowerCase() === trimmedName.toLowerCase())) {
        alert("Category name is empty or already exists."); return;
    }
    setFormData(prev => ({ ...prev, sizeCategories: [...(prev.sizeCategories || []), { categoryName: trimmedName, sizes: [] }] }));
    setNewCategoryName('');
  };

  const removeCategory = (i: number) => setFormData(prev => ({ ...prev, sizeCategories: (prev.sizeCategories || []).filter((_, idx) => idx !== i) }));
  const addSize = (i: number) => {
      const size = newSizeInputs[i]?.trim();
      if (size && formData.sizeCategories) {
          const newCats = formData.sizeCategories.map(c => ({...c, sizes: [...c.sizes]}));
          if (!newCats[i].sizes.includes(size)) {
              newCats[i].sizes.push(size);
              setFormData(prev => ({ ...prev, sizeCategories: newCats }));
              setNewSizeInputs(prev => ({ ...prev, [i]: '' }));
          }
      }
  };
  const removeSize = (catIdx: number, sizeIdx: number) => {
    if (!formData.sizeCategories) return;
    const newCats = formData.sizeCategories.map(c => ({...c, sizes: [...c.sizes]}));
    newCats[catIdx].sizes.splice(sizeIdx, 1);
    setFormData(prev => ({ ...prev, sizeCategories: newCats }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.category) { alert('Please select a category.'); return; }
    setIsSubmitting(true);
    try {
      if (product) await updateProduct({ ...formData, id: product.id, createdAt: product.createdAt });
      else await addProduct(formData);
      onClose();
    } catch (error) { console.error("Failed to save product", error); } 
    finally { setIsSubmitting(false); }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50 p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
        <h2 className="text-2xl font-bold mb-4">{product ? 'Edit Product' : 'Add Product'}</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <Input label="Name" name="name" value={formData.name} onChange={handleChange} required />
          <Input label="Custom Product ID (for Admin)" name="customId" value={formData.customId || ''} onChange={handleChange} placeholder="e.g., SKU-12345" />
          <Textarea label="Description" name="description" value={formData.description} onChange={handleChange} rows={3} required />
          <div className="grid grid-cols-2 gap-4"><Input label="Price" name="price" type="number" step="0.01" value={formData.price} onChange={handleChange} required /><Input label="Old Price (Optional)" name="oldPrice" type="number" step="0.01" value={formData.oldPrice} onChange={handleChange} /></div>
          <div className="grid grid-cols-2 gap-4">
            <div>
                <label htmlFor="category" className="block text-sm font-medium text-gray-700">Category</label>
                <select id="category" name="category" value={formData.category} onChange={handleChange} required disabled={!!categoryLock} className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm text-gray-900 focus:outline-none focus:ring-teal-500 focus:border-teal-600 sm:text-sm disabled:bg-gray-100">
                    <option value="">Select a Category</option>
                    {categoryOptions.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
                </select>
                {categoryOptions.length === 0 && <p className="mt-1 text-xs text-red-500">No child categories found. Products can only be added to child categories.</p>}
            </div>
            <Input label="Shipping Fee" name="shippingFee" type="number" step="1" value={formData.shippingFee || 0} onChange={handleChange} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Size Categories</label>
            <div className="p-3 border rounded-md space-y-3">
              {(formData.sizeCategories || []).map((cat, i) => (
                  <fieldset key={i} className="bg-gray-50 p-3 rounded-lg border">
                      <legend className="font-semibold px-2 flex justify-between items-center w-full"><span>{cat.categoryName}</span><Button type="button" variant="danger" size="xs" onClick={() => removeCategory(i)}><Icons.trash className="w-3 h-3"/></Button></legend>
                      <div className="flex flex-wrap gap-2 pt-2">{cat.sizes.map((s, si) => (<span key={si} className="flex items-center bg-white border border-gray-300 px-2 py-1 rounded text-sm">{s}<button type="button" onClick={() => removeSize(i, si)} className="ml-2 text-red-500"><Icons.x className="w-3 h-3" /></button></span>))}</div>
                      <div className="flex gap-2 mt-2"><Input placeholder="Add size" value={newSizeInputs[i] || ''} onChange={(e) => setNewSizeInputs(p => ({...p, [i]: e.target.value}))} className="h-8 text-sm"/><Button type="button" size="sm" onClick={() => addSize(i)}>Add</Button></div>
                  </fieldset>
              ))}
            </div>
            <div className="mt-4 bg-gray-50 p-3 rounded-md border">
                <h4 className="text-sm font-bold mb-2">Add New Size Category</h4>
                <div className="flex gap-2 items-center"><Input placeholder="e.g., Shirt Size" value={newCategoryName} onChange={(e) => setNewCategoryName(e.target.value)} /><Button type="button" onClick={handleCreateAndAddCategory}>Create</Button></div>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Images</label>
            <div className="flex gap-2 my-2 border-b pb-3"><Button type="button" size="sm" variant={imageInputMode === 'upload' ? 'primary' : 'secondary'} onClick={() => setImageInputMode('upload')}>Upload</Button><Button type="button" size="sm" variant={imageInputMode === 'url' ? 'primary' : 'secondary'} onClick={() => setImageInputMode('url')}>URL</Button></div>
            {imageInputMode === 'upload' ? <Input type="file" multiple onChange={handleImageUpload} accept="image/*" disabled={isUploading} /> : <div className="flex gap-2"><Input placeholder="https://example.com/image.jpg" value={imageUrl} onChange={(e) => setImageUrl(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter') { e.preventDefault(); handleAddImageUrl(); }}}/><Button type="button" onClick={handleAddImageUrl} className="self-end">Add</Button></div>}
            {isUploading && <div className="mt-2"><Spinner size="sm" /></div>}
            {uploadError && <p className="mt-2 text-sm text-red-500">{uploadError}</p>}
            <div className="grid grid-cols-4 gap-2 mt-2">{formData.images.map((img, i) => (<div key={i} className="relative group"><ImageWithFallback src={img} className="w-full h-20 object-cover rounded" /><button type="button" onClick={() => setFormData({ ...formData, images: formData.images.filter((_, idx) => idx !== i) })} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100"><Icons.x className="w-3 h-3" /></button></div>))}</div>
          </div>
          <div className="space-y-2 border p-3 rounded-md bg-gray-50">
              <h4 className="font-semibold text-sm">Delivery & Returns</h4>
              <Input label="Delivery Time" name="deliveryTime" value={formData.deliveryTime} onChange={handleChange} />
              <div className="flex items-center gap-4">
                  <div className="flex items-center"><input type="checkbox" id="freeDelivery" name="freeDelivery" checked={formData.freeDelivery} onChange={handleChange} className="h-4 w-4 text-teal-600" /><label htmlFor="freeDelivery" className="ml-2 block text-sm">Free Delivery</label></div>
                  <div className="flex items-center"><input type="checkbox" id="easyReturn" name="easyReturn" checked={formData.easyReturn} onChange={handleChange} className="h-4 w-4 text-teal-600" /><label htmlFor="easyReturn" className="ml-2 block text-sm">Easy Return</label></div>
              </div>
              {formData.easyReturn && (<Input label="Return Policy" name="returnPolicy" value={formData.returnPolicy} onChange={handleChange} />)}
          </div>
          <div className="flex items-center"><input type="checkbox" id="isVisible" name="isVisible" checked={formData.isVisible} onChange={handleChange} className="h-4 w-4 text-teal-600" /><label htmlFor="isVisible" className="ml-2 block text-sm">Visible in store</label></div>
          <div className="flex justify-end gap-4 pt-4 border-t"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit" disabled={isSubmitting || isUploading}>{isSubmitting ? <Spinner size="sm" /> : (product ? 'Save Changes' : 'Add Product')}</Button></div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../../hooks/useStore';
import { Order, OrderStatus } from '../../types';
import { formatCurrency, safeLower, generateCartItemKey } from '../../utils/helpers';
import { Input } from '../../components/ui/Input';
import { Spinner } from '../../components/ui/Spinner';
import { Icons } from '../../components/icons/Icons';
import { Button } from '../../components/ui/Button';

const handleDownloadInvoice = (order: Order) => {
    const itemRows = order.items.map(item => {
        const selectedSizes = item.selectedSizes && Object.keys(item.selectedSizes).length > 0
            ? `<br/><small style="color: #666;">(${Object.entries(item.selectedSizes).map(([cat, size]) => `${cat}: ${size}`).join(', ')})</small>`
            : '';
        return `
        <tr class="item">
            <td>${item.name} (x${item.quantity})${selectedSizes}</td>
            <td>${formatCurrency(item.price * item.quantity)}</td>
        </tr>
    `}).join('');

    const invoiceHtml = `
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8" />
        <title>Invoice #${order.id.slice(0, 6)}</title>
        <style>
            body { font-family: 'Helvetica Neue', 'Helvetica', Helvetica, Arial, sans-serif; text-align: center; color: #777; }
            body h1 { font-weight: 300; margin-bottom: 0px; padding-bottom: 0px; color: #000; }
            .invoice-box { max-width: 800px; margin: auto; padding: 30px; border: 1px solid #eee; box-shadow: 0 0 10px rgba(0, 0, 0, 0.15); font-size: 16px; line-height: 24px; color: #555; }
            .invoice-box table { width: 100%; line-height: inherit; text-align: left; border-collapse: collapse; }
            .invoice-box table td { padding: 5px; vertical-align: top; }
            .invoice-box table tr td:nth-child(2) { text-align: right; }
            .invoice-box table tr.top table td { padding-bottom: 20px; }
            .invoice-box table tr.top table td.title { font-size: 45px; line-height: 45px; color: #333; }
            .invoice-box table tr.information table td { padding-bottom: 40px; }
            .invoice-box table tr.heading td { background: #eee; border-bottom: 1px solid #ddd; font-weight: bold; }
            .invoice-box table tr.details td { padding-bottom: 20px; }
            .invoice-box table tr.item td { border-bottom: 1px solid #eee; }
            .invoice-box table tr.item.last td { border-bottom: none; }
            .invoice-box table tr.total td:nth-child(2) { border-top: 2px solid #eee; font-weight: bold; }
            @media only screen and (max-width: 600px) {
                .invoice-box table tr.top table td, .invoice-box table tr.information table td { width: 100%; display: block; text-align: center; }
            }
        </style>
    </head>
    <body>
        <div class="invoice-box">
            <table>
                <tr class="top">
                    <td colspan="2">
                        <table>
                            <tr>
                                <td class="title">
                                    <h1>ALI CART</h1>
                                </td>
                                <td>
                                    Invoice #: ${order.id.slice(0, 6)}<br />
                                    Created: ${new Date(order.createdAt).toLocaleDateString()}<br />
                                </td>
                            </tr>
                        </table>
                    </td>
                </tr>
                <tr class="information">
                    <td colspan="2">
                        <table>
                            <tr>
                                <td>
                                    <strong>Bill To:</strong><br />
                                    ${order.customerName}<br />
                                    ${order.customerAddress}<br />
                                    ${order.landmark ? `${order.landmark}<br />` : ''}
                                    ${order.city}, ${order.province}<br />
                                    ${order.customerPhone}<br />
                                    ${order.email || ''}
                                </td>
                            </tr>
                        </table>
                    </td>
                </tr>
                <tr class="heading">
                    <td>Payment Method</td>
                    <td></td>
                </tr>
                <tr class="details">
                    <td>${order.paymentMethod}</td>
                    <td></td>
                </tr>
                <tr class="heading">
                    <td>Item</td>
                    <td>Price</td>
                </tr>
                ${itemRows}
                <tr class="total">
                    <td></td>
                    <td>Subtotal: ${formatCurrency(order.total - order.shippingFee)}</td>
                </tr>
                <tr class="total">
                    <td></td>
                    <td>Shipping: ${formatCurrency(order.shippingFee)}</td>
                </tr>
                <tr class="total">
                    <td></td>
                    <td><strong>Total: ${formatCurrency(order.total)}</strong></td>
                </tr>
            </table>
        </div>
    </body>
    </html>
    `;

    const blob = new Blob([invoiceHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `invoice-${order.id.slice(0, 6)}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
};

const CopyableText = ({ text }: { text: string }) => {
    const handleCopy = () => {
        navigator.clipboard.writeText(text).then(() => {
            alert('ID Copied!');
        }, (err) => {
            console.error('Could not copy text: ', err);
            alert('Failed to copy ID.');
        });
    };

    return (
        <div className="flex items-center gap-2">
            <span className="font-mono bg-gray-100 p-1 rounded text-xs">{text}</span>
            <button onClick={handleCopy} title="Copy ID" className="text-gray-500 hover:text-gray-800">
                <Icons.copy className="w-4 h-4" />
            </button>
        </div>
    );
};

const OrderDetailsModal = ({ order, onClose }: { order: Order | null; onClose: () => void }) => {
    if (!order) return null;
    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50 p-4">
            <div className="bg-white rounded-lg p-4 w-full max-w-lg max-h-[90vh] overflow-y-auto">
                <div className="flex justify-between items-center">
                     <h2 className="text-xl font-bold mb-4">Order #{order.id.slice(0, 6)}</h2>
                     <button onClick={onClose} className="text-gray-500 hover:text-gray-800"><Icons.x /></button>
                </div>
                <div className="space-y-4 text-sm">
                    <div>
                        <h3 className="font-semibold mb-1 text-gray-600">Customer Details</h3>
                        <p><strong>Name:</strong> {order.customerName}</p>
                        <p><strong>Phone:</strong> {order.customerPhone}</p>
                        <p><strong>Email:</strong> {order.email || 'Not Provided'}</p>
                        <p><strong>Address:</strong> {`${order.customerAddress}, ${order.city}, ${order.province}`}</p>
                        {order.landmark && <p><strong>Landmark:</strong> {order.landmark}</p>}
                    </div>
                     <div>
                        <h3 className="font-semibold mb-1 text-gray-600">Order Information</h3>
                        <p><strong>Payment:</strong> {order.paymentMethod}</p>
                        <p><strong>Date:</strong> {new Date(order.createdAt).toLocaleString()}</p>
                    </div>

                    <div className="border-t pt-4">
                        <h3 className="font-semibold mb-2">Items:</h3>
                        {order.items.map(item => (
                            <div key={generateCartItemKey(item)} className="flex justify-between items-start py-2">
                                <div>
                                    <p className="font-medium">{item.name} x {item.quantity}</p>
                                    {item.customId && (
                                        <div className="pl-2 mt-1 text-xs text-gray-500 flex items-center gap-2">
                                        <span>Custom ID:</span> <CopyableText text={item.customId} />
                                        </div>
                                    )}
                                    <div className="pl-2 text-xs text-gray-500">
                                        {item.selectedSizes && Object.entries(item.selectedSizes).length > 0 && (
                                            <p className="text-pink-600 font-semibold">
                                                {Object.entries(item.selectedSizes).map(([cat, size]) => `${cat}: ${size}`).join(', ')}
                                            </p>
                                        )}
                                        {item.deliveryTime && <p>Delivery: {item.deliveryTime}</p>}
                                        {item.easyReturn ? 
                                            <p>Return: {item.returnPolicy || 'Available'}</p> 
                                            : <p>Return: Not Available</p>}
                                        {item.additionalInfo && <p className="text-blue-600">Notes: {item.additionalInfo}</p>}
                                    </div>
                                </div>
                                <span className="font-medium">{formatCurrency(item.price * item.quantity)}</span>
                            </div>
                        ))}
                    </div>
                     <div className="border-t pt-4 font-semibold text-base">
                        <div className="flex justify-between"><span>Subtotal</span><span>{formatCurrency(order.total - order.shippingFee)}</span></div>
                        <div className="flex justify-between"><span>Shipping</span><span>{formatCurrency(order.shippingFee)}</span></div>
                        <div className="flex justify-between text-lg"><span>Total</span><span>{formatCurrency(order.total)}</span></div>
                    </div>
                </div>
                <div className="text-right mt-6">
                    <Button variant="secondary" onClick={onClose}>Close</Button>
                </div>
            </div>
        </div>
    );
};

const ManageOrders = () => {
    const { orders, updateOrderStatus, deleteOrder, isLoading } = useStore();
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('All');
    const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);

    const filteredOrders = useMemo(() => {
        return orders.filter(order => {
            const searchTermLower = safeLower(searchTerm);
            const matchesSearch = safeLower(order.customerName).includes(searchTermLower) || safeLower(order.customerPhone).includes(searchTermLower) || safeLower(order.id).includes(searchTermLower);
            const matchesStatus = statusFilter === 'All' || order.status === statusFilter;
            return matchesSearch && matchesStatus;
        });
    }, [orders, searchTerm, statusFilter]);

    const handleDelete = (orderId: string) => {
        if (window.confirm('Are you sure you want to permanently delete this order? This action cannot be undone.')) {
            deleteOrder(orderId);
        }
    };

    return (
        <div>
            <h1 className="text-2xl md:text-3xl font-bold text-gray-800 mb-4">Manage Orders</h1>
            <div className="bg-white p-3 rounded-lg shadow-sm mb-4 flex flex-col md:flex-row gap-4">
                <Input
                    placeholder="Search by name, phone, or ID..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="flex-grow"
                />
                <select 
                    value={statusFilter} 
                    onChange={e => setStatusFilter(e.target.value)}
                    className="mt-1 block w-full md:w-auto px-3 py-2 bg-white border border-gray-300 rounded-md shadow-sm text-gray-900 focus:outline-none focus:ring-pink-500 focus:border-pink-500 text-sm"
                >
                    <option value="All">All Statuses</option>
                    {Object.values(OrderStatus).map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>

             {/* Mobile Card View */}
            <div className="md:hidden space-y-3">
                {isLoading && orders.length === 0 ? (
                    <div className="text-center p-8"><Spinner/></div>
                ) : filteredOrders.map(order => (
                    <div key={order.id} className="bg-white rounded-lg shadow-sm p-3 space-y-2 text-sm">
                         <div className="flex justify-between items-start">
                            <div>
                                <p className="font-bold text-gray-800">{order.customerName}</p>
                                <p className="text-xs text-gray-500">{order.customerPhone}</p>
                                <p className="text-xs text-gray-500">{new Date(order.createdAt).toLocaleDateString()}</p>
                            </div>
                            <p className="font-bold text-base text-pink-600">{formatCurrency(order.total)}</p>
                        </div>
                        <div className="flex justify-between items-center border-t pt-2">
                             <select
                                value={order.status}
                                onChange={(e) => updateOrderStatus(order.id, e.target.value as OrderStatus)}
                                className={`text-xs rounded-full px-2 py-1 border-2 focus:outline-none ${
                                    order.status === OrderStatus.Delivered ? 'bg-green-100 text-green-800 border-green-200' :
                                    order.status === OrderStatus.Cancelled ? 'bg-red-100 text-red-800 border-red-200' :
                                    'bg-yellow-100 text-yellow-800 border-yellow-200'
                                }`}
                            >
                                {Object.values(OrderStatus).map(status => (
                                    <option key={status} value={status}>{status}</option>
                                ))}
                            </select>
                            <div className="flex items-center gap-1">
                                <Button variant="ghost" size="sm" onClick={() => setSelectedOrder(order)} title="View Details"><Icons.eye className="w-5 h-5"/></Button>
                                <Button variant="ghost" size="sm" onClick={() => handleDownloadInvoice(order)} title="Download Invoice"><Icons.download className="w-5 h-5"/></Button>
                                <Button variant="ghost" size="sm" onClick={() => handleDelete(order.id)} className="text-red-600" title="Delete Order"><Icons.trash className="w-5 h-5"/></Button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Desktop Table View */}
            <div className="hidden md:block bg-white rounded-lg shadow-sm overflow-x-auto">
                <table className="w-full">
                    <thead className="bg-gray-50">
                        <tr className="text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
                            <th className="p-3">Customer</th>
                            <th className="p-3">Phone</th>
                            <th className="p-3">Total</th>
                            <th className="p-3">Date</th>
                            <th className="p-3">Status</th>
                            <th className="p-3 whitespace-nowrap">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200">
                        {isLoading && orders.length === 0 ? (
                             <tr><td colSpan={6} className="text-center p-8"><Spinner/></td></tr>
                        ) : filteredOrders.map(order => (
                            <tr key={order.id} className="hover:bg-gray-50 text-sm">
                                <td className="p-3 font-medium">{order.customerName}</td>
                                <td className="p-3 text-gray-600">{order.customerPhone}</td>
                                <td className="p-3 font-semibold text-gray-800">{formatCurrency(order.total)}</td>
                                <td className="p-3 text-gray-600">{new Date(order.createdAt).toLocaleDateString()}</td>
                                <td className="p-3">
                                     <select
                                        value={order.status}
                                        onChange={(e) => updateOrderStatus(order.id, e.target.value as OrderStatus)}
                                        className={`text-xs rounded-full px-2 py-1 border-2 focus:outline-none ${
                                            order.status === OrderStatus.Delivered ? 'bg-green-100 text-green-800 border-green-200' :
                                            order.status === OrderStatus.Cancelled ? 'bg-red-100 text-red-800 border-red-200' :
                                            order.status === OrderStatus.OnTheWay ? 'bg-blue-100 text-blue-800 border-blue-200' :
                                            'bg-yellow-100 text-yellow-800 border-yellow-200'
                                        }`}
                                    >
                                        {Object.values(OrderStatus).map(status => (
                                            <option key={status} value={status}>{status}</option>
                                        ))}
                                    </select>
                                </td>
                                <td className="p-3 whitespace-nowrap">
                                    <div className="flex items-center gap-3">
                                        <button onClick={() => setSelectedOrder(order)} className="text-blue-600 hover:text-blue-800" title="View Details"><Icons.eye className="w-5 h-5"/></button>
                                        <button onClick={() => handleDownloadInvoice(order)} className="text-gray-600 hover:text-gray-800" title="Download Invoice"><Icons.download className="w-5 h-5"/></button>
                                        <button onClick={() => handleDelete(order.id)} className="text-red-600 hover:text-red-800" title="Delete Order"><Icons.trash className="w-5 h-5"/></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                 {filteredOrders.length === 0 && !isLoading && (
                    <p className="text-center p-8 text-gray-500">No orders found.</p>
                )}
            </div>
             <OrderDetailsModal order={selectedOrder} onClose={() => setSelectedOrder(null)} />
        </div>
    );
};

export default ManageOrders;

