import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Icons } from './icons/Icons';
import { Button } from './ui/Button';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// FIX: Explicitly extending from Component with Props and State generics to ensure props.children and state properties are correctly recognized by TypeScript.
export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
    };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error in React component:", error, errorInfo);
  }

  handleReload = () => {
    // Clear cache-busting reload flag if present from lazyRetry
    Object.keys(window.sessionStorage).forEach(key => {
      if (key.startsWith('retry-')) window.sessionStorage.removeItem(key);
    });
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-gray-50 p-4 text-center">
          <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-gray-100">
