      } else {
        setAppliedCoupon(null);
        setCouponError(`Coupon requirements not met. Min bill: ${appliedCoupon.minBill}, Min products: ${appliedCoupon.minProducts}.`);
      }
    }

    const finalTotal = sub + shipFee - discAmt;
    return { subtotal: sub, totalProducts: prodCount, shippingFee: shipFee, discountAmount: discAmt, total: finalTotal };
  }, [cart, settings, appliedCoupon]);

  const handleApplyCoupon = () => {
    setCouponError('');
    setAppliedCoupon(null);
    const now = Date.now();
    const coupon = coupons.find(c => c.code.toLowerCase() === couponCode.toLowerCase() && c.validFrom <= now && c.validTo >= now);

    if (coupon) {
      if (subtotal >= coupon.minBill && totalProducts >= coupon.minProducts) {
        setAppliedCoupon(coupon);
        setCouponCode('');
      } else {
        setCouponError('Your order does not meet the requirements for this coupon.');
      }
    } else {
      setCouponError('Invalid or expired coupon code.');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;
    setIsPlacingOrder(true);
    try {
      const order: Omit<Order, 'id' | 'createdAt' | 'customerId'> = {
        ...formData,
        items: cart,
        total,
        shippingFee,
        appliedCoupon: appliedCoupon?.code,
        discountAmount,
        status: OrderStatus.Pending,
      };
      await addOrder(order);
      navigate('/order-success');
    } catch (err) {
      console.error("Order placement failed:", err);
      alert('Failed to place order. Please try again.');
    } finally {
      setIsPlacingOrder(false);
    }
  };

  const selectedPaymentMethod = useMemo(() => {
    return (settings?.paymentMethods || []).find(p => p.id === formData.paymentMethod);
  }, [settings, formData.paymentMethod]);

  const whatsappConfirmationNumber = useMemo(() => {
    const details = selectedPaymentMethod?.details || '';
    const numberRegex = /(\+92|92|0)?3\d{2}[- ]?\d{7}/;
    const match = details.match(numberRegex);
    return match ? match[0] : settings?.whatsappNumber;
  }, [selectedPaymentMethod, settings]);

  const whatsappLink = `https://wa.me/${normalizePhone(whatsappConfirmationNumber || '')}`;

  if (cart.length === 0) return null;

  return (
    <div className="container mx-auto">
      <h1 className="text-3xl font-bold text-gray-800 mb-4">Checkout</h1>
      <form onSubmit={handleSubmit} className="grid lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white p-4 rounded-lg shadow-sm">
            <h2 className="text-xl font-bold mb-3">Shipping Information</h2>
            <div className="grid sm:grid-cols-2 gap-4">
              <FormField name="customerName" label="Full Name *" error={errors.customerName}>
                <Input id="customerName" name="customerName" value={formData.customerName} onChange={handleChange} required />
              </FormField>
              <FormField name="customerPhone" label="Phone Number *" error={errors.customerPhone}>
                <Input id="customerPhone" name="customerPhone" type="tel" value={formData.customerPhone} onChange={handleChange} required />
              </FormField>
              <FormField name="email" label="Email Address (Optional)" error={errors.email}>
                <Input id="email" name="email" type="email" value={formData.email} onChange={handleChange} />
              </FormField>
              <FormField name="province" label="Province *" error={errors.province}>
                <select id="province" name="province" value={formData.province} onChange={handleChange} required className="mt-1 block w-full px-3 py-2 bg-white border border-gray-300 rounded-lg shadow-sm text-gray-900 focus:outline-none focus:ring-teal-500 focus:border-teal-600 sm:text-sm">
                  <option value="">Select Province</option>
                  {provinces.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </FormField>
              <FormField name="city" label="City *" error={errors.city}>
                <Input id="city" name="city" value={formData.city} onChange={handleChange} required />
              </FormField>
              <FormField name="landmark" label="Landmark / Area (Optional)" error={errors.landmark}>
                <Input id="landmark" name="landmark" value={formData.landmark} onChange={handleChange} />
              </FormField>
              <div className="sm:col-span-2">
                <FormField name="customerAddress" label="Full Address (House #, Street, Area) *" error={errors.customerAddress}>
                  <Textarea id="customerAddress" name="customerAddress" value={formData.customerAddress} onChange={handleChange} required rows={3} />
                </FormField>
              </div>
            </div>
          </div>
          <div className="bg-white p-4 rounded-lg shadow-sm">
            <h2 className="text-xl font-bold mb-3">Payment Method</h2>
            <div className="space-y-2">
              {(settings?.paymentMethods || []).map(method => (
                <label key={method.id} className="flex items-center p-3 border rounded-lg cursor-pointer has-[:checked]:bg-teal-50 has-[:checked]:border-teal-500 transition-colors">
                  <input type="radio" name="paymentMethod" value={method.id} checked={formData.paymentMethod === method.id} onChange={handleChange} className="h-4 w-4 text-teal-600 border-gray-300 focus:ring-teal-500"/>
                  <span className="ml-3">
                    <span className="font-semibold text-gray-800">{method.name}</span>
                    <span className="block text-sm text-gray-500">{method.details}</span>
                  </span>
                </label>
              ))}
            </div>
            {selectedPaymentMethod && selectedPaymentMethod.id !== 'cod' && (
              <div className="mt-4 bg-blue-50 border-l-4 border-blue-500 text-blue-800 p-4 rounded-r-md flex items-start gap-3">
                  <a href={whatsappLink} target="_blank" rel="noopener noreferrer" className="flex-shrink-0 pt-1" aria-label="Send payment confirmation on WhatsApp">
                      <Icons.whatsapp className="w-6 h-6 text-blue-600" />
                  </a>
                  <div>
                      <h4 className="font-bold">Payment Confirmation: {selectedPaymentMethod.name}</h4>
                      <p className="text-sm mt-1">
                          After payment, please send your screenshot to: <br/>
                          <strong className="font-mono">{whatsappConfirmationNumber}</strong>
                      </p>
                  </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-1">
          <div className="bg-white p-4 rounded-lg shadow-sm sticky top-24">
            <h2 className="text-2xl font-bold border-b pb-3 mb-3">Your Order</h2>
            <div className="space-y-2 max-h-60 overflow-y-auto pr-2">
              {cart.map(item => (
                <div key={generateCartItemKey(item)} className="flex items-center gap-3">
                    <span className="font-medium text-sm line-clamp-1 flex-grow">{item.name} x {item.quantity}</span>
                    <span className="text-sm">{formatCurrency(item.price * item.quantity)}</span>
                    <button type="button" onClick={() => removeFromCart(item.id, item.selectedSizes)}><Icons.trash className="w-4 h-4 text-red-500"/></button>
                </div>
              ))}
            </div>
            <div className="mt-4 pt-4 border-t">
                <div className="flex gap-2">
                    <Input placeholder="Coupon Code" value={couponCode} onChange={e => setCouponCode(e.target.value.toUpperCase())} />
                    <Button type="button" onClick={handleApplyCoupon} variant="secondary" className="flex-shrink-0">Apply</Button>
                </div>
                {couponError && <p className="text-xs text-red-600 mt-1">{couponError}</p>}
            </div>
            <div className="space-y-2 mt-4 pt-4 border-t">
              <div className="flex justify-between"><span>Subtotal</span><span>{formatCurrency(subtotal)}</span></div>
              {appliedCoupon && <div className="flex justify-between text-green-600"><span>Discount ({appliedCoupon.code})</span><span>-{formatCurrency(discountAmount)}</span></div>}
              <div className="flex justify-between"><span>Shipping</span><span>{formatCurrency(shippingFee)}</span></div>
              <div className="flex justify-between font-bold text-xl border-t pt-3 mt-3"><span>Total</span><span>{formatCurrency(total)}</span></div>
            </div>
            <Button type="submit" className="w-full mt-4" size="lg" disabled={isPlacingOrder}>
              {isPlacingOrder ? <Spinner size="sm" /> : `Place Order (${formatCurrency(total)})`}
            </Button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default Checkout;

import React, { ErrorInfo, ReactNode } from 'react';
import { Icons } from './icons/Icons';
import { Button } from './ui/Button';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// FIX: Explicitly extending from Component with Props and State generics to ensure props.children and state properties are correctly recognized by TypeScript.
// Fix: Use React.Component directly to resolve issues with props not being found on the class type.
export class ErrorBoundary extends React.Component<Props, State> {
  // FIX: Initialize state as a class property instead of in the constructor.
  // This correctly declares the 'state' property on the class, resolving errors where TypeScript could not find 'state' and 'props'.
  state: State = {
    hasError: false,
    error: null,
  };

  // FIX: Added constructor to explicitly pass props to the parent constructor, ensuring `this.props` is available.
  constructor(props: Props) {
    super(props);
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error in React component:", error, errorInfo);
  }

  handleReload = () => {
    // Clear cache-busting reload flag if present from lazyRetry
    Object.keys(window.sessionStorage).forEach(key => {
        if(key.startsWith('retry-')) window.sessionStorage.removeItem(key);
    });
    window.location.reload();
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-gray-50 p-4 text-center">
          <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full border border-gray-100">
            <div className="bg-red-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
               <Icons.refresh className="w-8 h-8 text-red-500" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800 mb-2">Something went wrong</h1>
            <p className="text-gray-500 mb-6">
              We encountered an unexpected error while displaying this page.
            </p>

            {/* Safe error message display */}
            <div className="bg-gray-100 p-3 rounded text-left text-xs font-mono text-red-600 mb-6 overflow-auto max-h-32 border border-gray-200">
                {this.state.error?.message || 'Unknown Application Error'}
            </div>

            <Button onClick={this.handleReload} className="w-full" size="lg">
              Reload Application
            </Button>
            <p className="mt-4 text-xs text-gray-400">
              If the problem persists, please try clearing your browser cache.
            </p>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}
